export interface ChatRoom {
  id: string;
  name: string;
  description: string;
  topic: string;
  category: "public" | "academic" | "advisors" | "vip" | "direct" | "official";
  type: "public" | "academic" | "private" | "direct" | "announcement" | "channel";
  membersCount: number;
  isPinned?: boolean;
  isMainPublicChannel?: boolean;
  isSupportRoom?: boolean;
  isLocked?: boolean;
  isAdvisorStudentGroup?: boolean;
  directStudentId?: string;
  directStudentName?: string;
  studentId?: string;
  participants?: string[];
  approvalStatus?: "approved" | "pending_approval" | "rejected";
  createdAt: string;
  updatedAt: string;
}

export interface ChatMessage {
  id: string;
  roomId: string;
  senderId: string;
  senderName: string;
  senderRole: "student" | "advisor" | "parent" | "admin" | "guest";
  senderBadge?: string;
  senderAvatar?: string;
  content: string;
  text: string;
  timestamp: string;
  createdAt?: string;
  isPinned?: boolean;
  replyTo?: {
    id: string;
    senderName: string;
    text: string;
  };
  reactions?: Record<string, string[]>;
}

