export function getSubjectTaxonomy(subject: string): SubjectTaxonomy | undefined {
  if (SUBJECT_TAXONOMIES[subject]) return SUBJECT_TAXONOMIES[subject];
  for (const [key, val] of Object.entries(SUBJECT_TAXONOMIES)) {
    if (subject.includes(key) || key.includes(subject)) return val;
  }
  return undefined;
}
